package com.foodbridge.consumer;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="consumer_profiles") public class ConsumerProfile {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true) private String email;private String fullName;private String phone;private String preferredPickupArea;private LocalDateTime createdAt=LocalDateTime.now();protected ConsumerProfile(){}public ConsumerProfile(String email,String fullName,String phone,String area){this.email=email;this.fullName=fullName;this.phone=phone;this.preferredPickupArea=area;}public Long getId(){return id;}public String getEmail(){return email;}public String getFullName(){return fullName;}public String getPhone(){return phone;}public String getPreferredPickupArea(){return preferredPickupArea;}public LocalDateTime getCreatedAt(){return createdAt;}public void update(String n,String p,String a){fullName=n;phone=p;preferredPickupArea=a;}}
